import{_ as o,o as t,c as a,a6 as n}from"./chunks/framework.BBdhcoHf.js";const u=JSON.parse('{"title":"ADR-016: Relay Server Design","description":"","frontmatter":{},"headers":[],"relativePath":"adr/016-relay-server-design.md","filePath":"adr/016-relay-server-design.md","lastUpdated":1772054201000}'),i={name:"adr/016-relay-server-design.md"};function r(s,e,d,l,c,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /adr/016-relay-server-design.md for this page in Markdown format</div><h1 id="adr-016-relay-server-design" tabindex="-1">ADR-016: Relay Server Design <a class="header-anchor" href="#adr-016-relay-server-design" aria-label="Permalink to “ADR-016: Relay Server Design”">​</a></h1><ul><li><strong>Date</strong>: 2026-02-25</li><li><strong>Status</strong>: Accepted</li><li><strong>Affects</strong>: Runtime, SDK, Transport</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The hosted Sideband relay is the infrastructure that enables browser ↔ daemon communication through NAT. It is the bridge between <code>sbrpClientNegotiator</code> (browser/client) and <code>sbrpDaemonNegotiator</code> (local daemon). Without a relay endpoint, the E2EE value proposition is theoretical.</p><p>The relay must:</p><ol><li>Accept WebSocket connections from daemons and clients.</li><li>Pair them by <code>daemonId</code> and session parameters.</li><li>Forward binary frames between them without decryption.</li><li>Handle disconnects, session cleanup, and pause/resume signaling.</li></ol><p>The platform is built on Cloudflare Workers. Any relay design must operate within Workers constraints: no persistent memory between requests, stateless execution model by default.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="_1-cloudflare-durable-objects-—-one-do-per-daemonid" tabindex="-1">1. Cloudflare Durable Objects — one DO per <code>daemonId</code> <a class="header-anchor" href="#_1-cloudflare-durable-objects-—-one-do-per-daemonid" aria-label="Permalink to “1. Cloudflare Durable Objects — one DO per daemonId”">​</a></h3><p>Each active daemon routing shard (one daemon + N clients) is owned by a Durable Object keyed by <code>daemonId</code>. The DO holds WebSocket connections and forwards frames between paired endpoints.</p><p><strong>Rationale:</strong> Durable Objects are the only Cloudflare-native primitive that provides:</p><ul><li>Persistent in-memory state across WebSocket lifetime</li><li>Co-location of related connections within a single execution context</li><li>Atomic session lifecycle management without external coordination</li></ul><p>Alternatives considered and rejected:</p><table tabindex="0"><thead><tr><th>Option</th><th>Reason rejected</th></tr></thead><tbody><tr><td>KV / R2 for state</td><td>No push semantics; polling is incompatible with WebSocket latency</td></tr><tr><td>Global Workers state</td><td>Stateless; no connection affinity</td></tr><tr><td>External Redis / Postgres</td><td>Adds infrastructure dependency and egress latency</td></tr></tbody></table><h3 id="_2-frame-forwarding-is-opaque-relay-never-decrypts" tabindex="-1">2. Frame forwarding is opaque (relay never decrypts) <a class="header-anchor" href="#_2-frame-forwarding-is-opaque-relay-never-decrypts" aria-label="Permalink to “2. Frame forwarding is opaque (relay never decrypts)”">​</a></h3><p>The relay forwards raw binary WebSocket messages without parsing SBRP frame content. Session key material never exists on the relay — only the two endpoints (daemon and client) hold session keys.</p><p><strong>Rationale:</strong> This is a security invariant of SBRP (see <code>docs/protocols/sbrp/threat-model.md</code>). Violating it would undermine the core E2EE promise. The relay identifies sessions by <code>daemonId</code> and validated token claims — it never reads frame payloads.</p><h3 id="_3-authentication-before-websocket-upgrade" tabindex="-1">3. Authentication before WebSocket upgrade <a class="header-anchor" href="#_3-authentication-before-websocket-upgrade" aria-label="Permalink to “3. Authentication before WebSocket upgrade”">​</a></h3><p>All connections authenticate before the WebSocket handshake is completed. Authentication is handled in the edge Worker (not the Durable Object) to prevent unauthenticated connections from consuming DO resources.</p><p><strong>Auth model:</strong></p><ul><li><strong>Daemon connections</strong>: Long-lived API key tied to an account and <code>daemonId</code>. Validated against the database on first connection; cached for the DO lifetime.</li><li><strong>Client connections</strong>: Short-lived signed token (JWT) scoped to a <code>daemonId</code> and TTL. Issued by the API server after the client authenticates.</li></ul><h3 id="_4-token-based-session-routing" tabindex="-1">4. Token-based session routing <a class="header-anchor" href="#_4-token-based-session-routing" aria-label="Permalink to “4. Token-based session routing”">​</a></h3><p>Connection routing uses a fixed endpoint with token-derived routing:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wss://{region}.relay.sideband.cloud?token=&lt;jwt&gt;</span></span></code></pre></div><p>The routing key (<code>daemonId</code>) is derived exclusively from validated token claims (<code>did</code>). It MUST NOT be duplicated in the URL path — the token is the single source of truth for <code>daemonId</code>, <code>role</code>, and <code>sid</code>. This eliminates URL-token mismatch validation, reduces metadata leakage in logs, and removes client-side URL construction complexity.</p><p>The edge Worker validates the JWT before upgrade, extracts <code>did</code>, and routes to the Durable Object keyed by <code>daemonId</code>. No database lookup is needed on every frame — the DO ID is deterministic from the token&#39;s <code>did</code> claim.</p><p>Token delivery:</p><ul><li><strong>Query parameter</strong>: <code>?token=&lt;jwt&gt;</code> — required for browser WebSocket compatibility</li><li><strong>Authorization header</strong>: <code>Authorization: Bearer &lt;jwt&gt;</code> — preferred for programmatic clients (daemons)</li></ul><p>Security note: query-string tokens MUST be short-lived and redacted from logs/analytics.</p><h3 id="_5-pause-resume-signaling" tabindex="-1">5. Pause/resume signaling <a class="header-anchor" href="#_5-pause-resume-signaling" aria-label="Permalink to “5. Pause/resume signaling”">​</a></h3><p>When a client connection drops, the relay emits <code>Control(session_ended)</code> to the daemon; the daemon&#39;s <code>AcceptedPeer</code> transitions to <code>closed</code> (no pause semantics for client drops — clients are ephemeral from the relay&#39;s perspective).</p><p>When the daemon connection closes unexpectedly, the DO emits <code>Control(session_paused)</code> to affected clients (relay-originated control), which maps to <code>SessionSignal{ type: &quot;session_paused&quot; }</code> in the SDK (see ADR-014). During <code>paused</code>, the relay does not promise payload buffering; SDK-side buffering policy (<code>connectionPolicy</code>, <code>eventPolicy</code>) remains authoritative. After daemon reconnect, the relay emits <code>Control(session_pending)</code> and only emits <code>Control(session_resumed)</code> after daemon <code>Signal(ready)</code> (see <code>docs/protocols/sbrp/state-machine.md</code>). If the session is terminated (e.g., daemon deregisters or auth expires), the relay emits <code>Control(session_ended)</code>. The client terminates the current session; retry behavior follows the client&#39;s retry policy (see ADR-014).</p><h2 id="invariants" tabindex="-1">Invariants <a class="header-anchor" href="#invariants" aria-label="Permalink to “Invariants”">​</a></h2><ul><li>Relay MUST NOT inspect SBRP frame payloads.</li><li>Session pairing MUST be deterministic from <code>daemonId</code> alone (no random sharding).</li><li>Unauthenticated WebSocket upgrades MUST be rejected at the edge Worker before reaching the DO.</li><li>A DO instance is authoritative for exactly one <code>daemonId</code>; multiple DOs for the same <code>daemonId</code> MUST NOT be allowed.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>sideband-platform/packages/relay/</code> — new package implementing the Durable Object and edge Worker routing logic.</li><li><code>apps/api/</code> — adds WebSocket upgrade endpoint routed to the relay DO.</li><li><code>db/</code> — adds relay session and API key tables.</li><li>Relay package has no dependency on <code>@sideband/peer</code>. Frame routing decisions come from authenticated connection context (<code>daemonId</code>, role, token claims), not SBP payload parsing.</li><li>Cloudflare Durable Object namespace must be declared in <code>wrangler.toml</code>.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li>ADR-009: Runtime Session Lifecycle</li><li>ADR-014: Peer SDK Session Signal Handling</li><li>ADR-015: P2P Direct Protocol (SBDP) — relay-assisted ICE signaling extension noted there</li><li><code>docs/protocols/sbrp/state-machine.md</code>: SBRP session states forwarded by relay</li><li><code>docs/protocols/sbrp/threat-model.md</code>: Security invariants the relay must uphold</li><li><code>docs/protocols/sbrp/control-codes.md</code>: Relay notification codes (pause, resume signals)</li></ul>',39)])])}const m=o(i,[["render",r]]);export{u as __pageData,m as default};
